def pre(p, q):
    # Valid scores: non-negative, and either both are at most 3 (game still
    # in progress with no earlier win possible), or the lead is at most 2
    # (any state reached before a winning point, including deuce-region states).
    return And(
        p >= 0,
        q >= 0,
        Or(
            And(p <= 3, q <= 3),
            And(p - q <= 2, q - p <= 2)
        )
    )

def post(p, q, r):
    a_wins = And(p >= 4, p - q >= 2)
    b_wins = And(q >= 4, q - p >= 2)
    return r == If(a_wins, 1, If(b_wins, 2, 0))
